package nativeui

import (
	"fmt"
	"strconv"
	"strings"

	"github.com/egoist/mygo/ui"
)

// nftState is the NFT page's state.
type nftState struct {
	// Mint form.
	name        string
	description string
	imageURL    string
	tokenURI    string
	creator     string
	// creatorPriv is the private half of a key pair generated by the Mint card,
	// shown once for copying and never stored by the service.
	creatorPriv string
	// creatorKeyNFTID is the asset minted with creatorPriv. Transfer/Burn can
	// reuse the key only while that asset is their subject and its owner is
	// still the creator; otherwise the button would sign for the wrong holder.
	creatorKeyNFTID string

	// Read forms.
	id    string
	owner string

	// filterOwner is the owner filter currently applied to the Collection
	// card, empty for the whole collection. It is separate from the owner
	// input so a refresh re-applies the filter the list is showing instead of
	// silently replacing a filtered list with every NFT while the field still
	// names an owner.
	filterOwner string
	// search narrows the shown collection by id or name, on top of the owner
	// filter; appliedSearch is the query the current highlight belongs to.
	search        string
	appliedSearch string

	// Each write form names its own NFT: one shared field meant typing an id
	// in the Transfer card silently retargeted Inspect, Burn and History too.
	transferID string
	burnID     string
	historyID  string

	nft     *NFTRow
	list    []NFTRow
	history []NFTOpRow
	// The detail and history readouts are caches keyed by the NFT they
	// describe. A selection or mint changes the id; without the key, a failed
	// read left the previous asset's details under the new id. The error keeps
	// a failed same-subject refresh visible.
	nftErr          error
	nftLoadedID     string
	historyErr      error
	historyLoadedID string
	// historyOffset pages the operation trail independently of the NFT
	// collection. hasMore uses one lookahead row so an exact final page does
	// not leave a dead Next control.
	historyOffset  int
	historyHasMore bool

	// Write forms.
	from      string
	to        string
	priv      string
	burnOwner string
	burnPriv  string
	// The two write cards have independent ids, so each tracks the subject
	// whose holder context it has applied. Manual id edits must clear the old
	// holder and signing key without touching the other card.
	transferSubjectID string
	transferOwnerID   string
	burnSubjectID     string
	burnOwnerID       string

	loadErr error

	// askBurn gates the irreversible burn, as the CLI's --confirm does.
	askBurn bool
	// opTab is the operation shown in the write column. Stacking Transfer,
	// Burn and History pushed the last two below the fold for no reason.
	opTab int
	// mintAdvanced holds the optional metadata fields behind a disclosure:
	// most mints only need a name and a creator.
	mintAdvanced bool

	status statusLine

	listTable    ui.ListState
	historyTable ui.ListState
	// burnTrigger receives focus when the destructive confirmation closes, and
	// generateControl takes it back when the one-time key card is dismissed.
	burnTrigger     ui.Handle
	generateControl ui.Handle
	creatorKeyCopy  ui.Handle
	// selected is the collection row chosen, -1 for none.
	selected int
	// limit/offset page the collection. A long-lived NFT store should not be
	// materialised in full just to show its newest hundred assets.
	limit   float64
	offset  int
	hasMore bool
}

const nftPageSize = 100
const nftHistoryPageSize = 100

func (a *App) loadNFT() {
	a.loadNFTPage(a.nft.offset)
}

// loadNFTPage commits offset only after a successful read, so a failed pager
// move keeps the previous page and its controls truthful.
func (a *App) loadNFTPage(offset int) bool {
	if a.services == nil {
		return false
	}
	// The collection is the page's entry point: an asset minted in another
	// session is otherwise reachable only by an id nobody wrote down. A filter
	// that is applied stays applied across refreshes and page switches.
	var (
		rows []NFTRow
		err  error
	)
	limit := int(a.nft.limit)
	if limit < 10 {
		limit = nftPageSize
	}
	if limit > maxListLimit {
		limit = maxListLimit
	}
	if offset < 0 {
		offset = 0
	}
	requestLimit := limit + 1
	if a.nft.filterOwner != "" {
		rows, err = a.services.ListNFTsPage(a.nft.filterOwner, requestLimit, offset)
	} else {
		rows, err = a.services.ListAllNFTsPage(requestLimit, offset)
	}
	a.nft.loadErr = err
	if err != nil {
		return false
	}
	if len(rows) == 0 && offset > 0 {
		return a.loadNFTPage(0)
	}
	a.nft.offset = offset
	a.nft.hasMore = len(rows) > limit
	if a.nft.hasMore {
		rows = rows[:limit]
	}
	a.nft.list = rows
	return true
}

func (a *App) nftView(c *ui.Context) {
	a.syncNFTSubjects()
	a.scrollPage(c, func() {
		guide(c, &a.guides.nft,
			"Mint an asset with a creator key, or select one in Collection. The creator is the first owner.",
			"Transfer or Burn in the right column; the current holder's private key signs. A generated creator key can be reused while the creator still holds the asset.",
			"History lists every mint, transfer and burn; Inspect shows the stored metadata and links.",
		)
		// The collection leads: what exists comes before adding to it, and the
		// cards below act on the row it selects.
		twoColumns(c, func() {
			a.nftRead(c)
			a.nftMint(c)
		}, func() {
			a.nftWrite(c)
		})
		a.renderNFTBurnDialog(c)
	})
}

func (a *App) nftMint(c *ui.Context) {
	formCard(c, "Mint NFT", "Create a unique asset owned by the creator key.", func() {
		a.nftMintBody(c)
	})
}

func (a *App) nftMintBody(c *ui.Context) {
	generated := false
	field(c, "Name", &a.nft.name)
	ui.Collapsible(c, tr("Optional details"), &a.nft.mintAdvanced, func() {
		textArea(c, "Description (optional)", &a.nft.description)
		field(c, "Image URL (optional)", &a.nft.imageURL)
		field(c, "Token URI (optional)", &a.nft.tokenURI)
	})
	fieldHint(c, "Creator (base64 public key)", "The creator becomes the first owner.", &a.nft.creator)
	ui.Row(c).Gap(8).Children(func() {
		if secondaryButton(c, "Generate key pair").Bind(&a.nft.generateControl).Clicked() {
			generated = a.generateNFTCreator()
		}
		if a.nft.creatorPriv != "" && quietButton(c, "Dismiss key").Clicked() {
			a.nft.creatorPriv = ""
			a.nft.generateControl.Focus(c)
		}
	})
	if a.nft.creatorPriv != "" {
		copyRow(c, "Creator private key", a.nft.creatorPriv, func() {
			a.nft.status = okStatus("Creator private key copied.")
		}).Bind(&a.nft.creatorKeyCopy)
		ui.Text(c, tr("This is the only copy of the creator key; the store keeps the public half.")).
			FontSize(textSize(c, 11)).TextColor(ui.Hex(auroraAmber))
	}
	if generated {
		a.nft.creatorKeyCopy.Focus(c)
	}
	ui.Row(c).Children(func() {
		if primaryButton(c, "Mint NFT").Disabled(!allSet(a.nft.name, a.nft.creator)).Clicked() {
			a.mintNFT()
		}
	})
}

// generateNFTCreator fills the Creator field from a fresh Ed25519 key pair and
// offers the private half for copying, the same handover as a token owner.
func (a *App) generateNFTCreator() bool {
	pub, priv, err := a.services.GenerateKeyPair()
	if err != nil {
		a.nft.status = errStatus(err)
		return false
	}
	a.nft.creator, a.nft.creatorPriv = pub, priv
	// A new pair belongs to no asset yet.
	a.nft.creatorKeyNFTID = ""
	a.nft.status = okStatus("Generated a creator key pair. Copy the private key now; it is not stored.")
	return true
}

// mintNFT mints the asset described by the Mint card's inputs.
func (a *App) mintNFT() {
	name, description := strings.TrimSpace(a.nft.name), strings.TrimSpace(a.nft.description)
	imageURL, tokenURI := strings.TrimSpace(a.nft.imageURL), strings.TrimSpace(a.nft.tokenURI)
	creator, creatorPriv := strings.TrimSpace(a.nft.creator), a.nft.creatorPriv
	if rejectIncomplete(&a.nft.status, "NFT name and creator are required.", name, creator) {
		return
	}
	a.runWrite("Minting NFT…", func() func() {
		n, err := a.services.MintNFT(name, description, imageURL, tokenURI, creator)
		return func() {
			if err != nil {
				a.nft.status = errStatus(err)
				return
			}
			a.rememberSuccessfulKey(n.Creator, creatorPriv)
			a.nft.status = okStatus("Minted %s (%s) at block %d", n.Name, n.ID, n.BlockHeight)
			// A just-minted asset is the page's subject. Clear a filter or search
			// that would hide it, highlight its row, and move the ids and open
			// readouts to it; leaving the collection on the previous owner's filter
			// made a successful mint look like nothing happened.
			a.nft.filterOwner, a.nft.owner = "", ""
			a.nft.search, a.nft.appliedSearch = "", ""
			a.loadNFTPage(0)
			// The new asset becomes the subject of every other card: the operator
			// just created it, so making them retype the id four times would be
			// busywork.
			a.nft.id, a.nft.transferID, a.nft.burnID, a.nft.historyID = n.ID, n.ID, n.ID, n.ID
			a.nft.creatorKeyNFTID = n.ID
			a.applyNFTSubject(n.Owner)
			a.selectNFTRow(n.ID)
			a.selectNFT(n.ID)
			a.nft.name, a.nft.description, a.nft.imageURL, a.nft.tokenURI = "", "", "", ""
		}
	})
}

// selectNFTRow highlights a record in the collection after a mint.
func (a *App) selectNFTRow(id string) {
	a.nft.selected = -1
	for i, n := range a.nft.list {
		if n.ID == id {
			a.nft.selected = i
			return
		}
	}
}

// applyNFTSubject moves the holder-shaped inputs to the asset the write cards
// act on. Private keys and the previous recipient are cleared on every subject
// change so a newly chosen or minted asset cannot be signed or sent with values
// left over from another one.
func (a *App) applyNFTSubject(owner string) {
	a.applyNFTTransferSubject(owner)
	a.applyNFTBurnSubject(owner)
}

func (a *App) applyNFTTransferSubject(owner string) {
	id := strings.TrimSpace(a.nft.transferID)
	a.nft.priv, a.nft.to = "", ""
	a.nft.from = owner
	a.nft.transferSubjectID = id
	if owner == "" {
		a.nft.transferOwnerID = ""
		return
	}
	a.nft.transferOwnerID = id
}

func (a *App) applyNFTBurnSubject(owner string) {
	id := strings.TrimSpace(a.nft.burnID)
	a.nft.burnPriv = ""
	a.nft.burnOwner = owner
	a.nft.burnSubjectID = id
	if owner == "" {
		a.nft.burnOwnerID = ""
		return
	}
	a.nft.burnOwnerID = id
}

// syncNFTSubjects reacts to ids typed directly into Transfer or Burn. The
// collection row and Inspect readout are the available local owner sources;
// an id neither one knows still clears the old holder rather than leaving it
// attached to the new asset.
func (a *App) syncNFTSubjects() {
	if id := strings.TrimSpace(a.nft.transferID); a.nft.transferSubjectID != id {
		a.applyNFTTransferSubject(a.nftOwnerForID(id))
	}
	if id := strings.TrimSpace(a.nft.burnID); a.nft.burnSubjectID != id {
		a.applyNFTBurnSubject(a.nftOwnerForID(id))
	}
}

func (a *App) nftOwnerForID(id string) string {
	if id == "" {
		return ""
	}
	if a.nft.nft != nil && a.nft.nftLoadedID == id {
		return a.nft.nft.Owner
	}
	for _, n := range a.nft.list {
		if n.ID == id {
			return n.Owner
		}
	}
	return ""
}

func (a *App) nftRead(c *ui.Context) {
	formCard(c, "Collection", "Every stored asset, newest first. Choose a row to load its id into the cards below.", func() {
		a.nftListBody(c)
	})
	formCard(c, "Inspect", "Look up one NFT by id, or narrow the collection to one owner.", func() {
		a.nftReadBody(c)
	})
}

func (a *App) nftReadBody(c *ui.Context) {
	field(c, "NFT ID", &a.nft.id)
	id := strings.TrimSpace(a.nft.id)
	ui.Row(c).Children(func() {
		if secondaryButton(c, "Get NFT").Disabled(!allSet(a.nft.id)).Clicked() {
			a.readNFTDetails()
		}
	})
	if a.nft.nftErr != nil && a.nft.nftLoadedID == id {
		loadWarning(c, "Couldn't load NFT", a.nft.nftErr, a.nft.nft != nil)
	}
	copyRow(c, "NFT ID", strings.TrimSpace(a.nft.id), nil)
	if n := a.nft.nft; n != nil && a.nft.nftLoadedID == id {
		rows := []readoutRow{
			{"Name", n.Name}, {"Owner", n.Owner}, {"Creator", n.Creator},
			{"Block", strconv.FormatInt(n.BlockHeight, 10)},
		}
		if n.Description != "" {
			rows = append(rows, readoutRow{"About", n.Description})
		}
		readout(c, rows)
		// URLs are long enough that the readout would clip them; the copy row
		// shows both ends and makes the stored value retrievable.
		copyRow(c, "Image URL", n.ImageURL, nil)
		copyRow(c, "Token URI", n.TokenURI, nil)
	}

	// The Collection card holds the whole collection; this narrows it to one
	// owner, and Show All restores everything.
	fieldHint(c, "Owner (base64 public key)", "Narrow the Collection card to one owner.", &a.nft.owner)
	ui.Row(c).Gap(8).Children(func() {
		if secondaryButton(c, "Filter by Owner").Disabled(!allSet(a.nft.owner)).Clicked() {
			a.filterNFTs()
		}
		if secondaryButton(c, "Show All").Clicked() {
			a.showAllNFTs()
		}
	})
}

func (a *App) readNFTDetails() {
	id := strings.TrimSpace(a.nft.id)
	if rejectIncomplete(&a.nft.status, "NFT ID is required for this read.", id) {
		return
	}
	a.clearNFTDetailsForAnotherSubject(id)
	if err := a.loadNFTDetails(id); err != nil {
		a.nft.status = errStatus(err)
	} else {
		a.nft.status = statusLine{}
	}
}

// filterNFTs applies the owner named in the field. It goes through loadNFT so
// the filter survives refreshes and a failed read keeps the rows already shown
// instead of blanking the collection.
func (a *App) filterNFTs() {
	next := strings.TrimSpace(a.nft.owner)
	if rejectIncomplete(&a.nft.status, "Owner is required to filter the collection.", next) {
		return
	}
	if next != a.nft.filterOwner {
		a.nft.list = nil
		a.nft.loadErr = nil
		a.nft.offset = 0
		a.nft.hasMore = false
	}
	a.nft.filterOwner = next
	a.nft.selected = -1
	a.loadNFTPage(0)
}

// showAllNFTs clears the filter and reloads the whole collection.
func (a *App) showAllNFTs() {
	a.nft.owner = ""
	if a.nft.filterOwner != "" {
		a.nft.list = nil
		a.nft.loadErr = nil
		a.nft.offset = 0
		a.nft.hasMore = false
	}
	a.nft.filterOwner = ""
	a.nft.selected = -1
	a.loadNFTPage(0)
}

// nftListBody draws the collection table.
func (a *App) nftListBody(c *ui.Context) {
	if a.nft.loadErr != nil && !loadWarning(c, "Failed to load NFTs", a.nft.loadErr, len(a.nft.list) > 0) {
		return
	}
	if len(a.nft.list) == 0 {
		if a.nft.filterOwner != "" {
			emptyNote(c, "No NFTs for this owner. Show All restores the collection.")
			return
		}
		emptyState(c, pageNFT, "No NFTs yet", "Mint an asset above to start the collection; it becomes the first holder’s token.")
		return
	}
	searchField(c, &a.nft.search, "Search NFTs").
		Description(tr("Search narrows the current page; use Previous/Next for older assets."))
	queryChanged := a.nft.search != a.nft.appliedSearch
	if queryChanged {
		a.nft.appliedSearch = a.nft.search
		a.nft.selected = -1
	}
	limit := int(a.nft.limit)
	if limit < 10 {
		limit = nftPageSize
	}
	if limit > maxListLimit {
		limit = maxListLimit
	}
	if previous, next := listPager(c, "NFT collection", a.nft.offset, len(a.nft.list), a.nft.hasMore); previous || next {
		target := a.nft.offset
		if previous {
			target = max(0, target-limit)
		} else {
			target += limit
		}
		if a.loadNFTPage(target) {
			a.nft.selected = -1
		}
		return
	}
	if a.nft.search != "" {
		hint(c, "Search narrows the current page; use Previous/Next for older assets.")
	}
	list := make([]NFTRow, 0, len(a.nft.list))
	for _, n := range a.nft.list {
		if containsFold(a.nft.search, n.ID, n.Name) {
			list = append(list, n)
		}
	}
	announceSearchResults(c, queryChanged, len(list))
	if len(list) == 0 {
		emptyNote(c, fmt.Sprintf(tr("No NFTs match “%s”."), strings.TrimSpace(a.nft.search)))
		return
	}
	if stackedRecords(c) {
		a.nftListRecords(c, list)
	} else {
		a.nft.listTable.Selected = &a.nft.selected
		table := namedTable(c, "NFT collection", &a.nft.listTable, []ui.TableColumn{
			{Title: tr("ID"), Width: 150},
			{Title: tr("Name"), MinWidth: 110},
			// A ledger height is an int64 and can reach nineteen digits. Give
			// the numeric column room that grows with the text size instead of
			// clipping the value that proves when the asset was recorded.
			{Title: tr("Block"), MinWidth: tableColumnWidth(c, 140), Align: ui.End},
		}, len(list), func(row, col int) {
			n := list[row]
			switch col {
			case 0:
				tableTextFull(c, shortID(n.ID), n.ID)
			case 1:
				tableText(c, n.Name)
			case 2:
				tableText(c, strconv.FormatInt(n.BlockHeight, 10))
			}
		})
		if table.Changed() {
			a.chooseNFT(list, a.nft.selected)
		}
	}
}

// nftListRecords keeps every collection fact readable when the three-column
// table no longer fits enlarged text. The complete id is visible before the
// selection copies it into four forms, and the whole panel is keyboard- and
// pointer-operable as one choice.
func (a *App) nftListRecords(c *ui.Context, list []NFTRow) {
	ui.Column(c).FillWidth().Gap(10).Children(func() {
		for i, nft := range list {
			i, nft := i, nft
			displayName := nft.Name
			if strings.TrimSpace(displayName) == "" {
				displayName = shortID(nft.ID)
			}
			selected := i == a.nft.selected
			record := selectableRecordPanel(c, selected,
				recordChoiceLabel(displayName, selected), func() {
					ui.Text(c, displayName).FontSize(textSize(c, 13)).Bold().
						TextColor(c.Theme().Text)
					recordMetric(c, "Block", strconv.FormatInt(nft.BlockHeight, 10), c.Theme().Text)
					recordField(c, "ID", nft.ID)
				})
			if record.Clicked() {
				a.chooseNFT(list, i)
			}
		}
	})
}

// chooseNFT is the one path that makes a collection row the subject of every
// asset card. Move and Burn also take the holder from the same row, so the
// operator never retypes a key the collection already knows.
func (a *App) chooseNFT(list []NFTRow, index int) {
	if index < 0 || index >= len(list) {
		return
	}
	a.nft.selected = index
	nft := list[index]
	a.nft.id, a.nft.transferID, a.nft.burnID, a.nft.historyID = nft.ID, nft.ID, nft.ID, nft.ID
	a.applyNFTSubject(nft.Owner)
	a.selectNFT(nft.ID)
}

func (a *App) nftWrite(c *ui.Context) {
	tabs(c, &a.nft.opTab, "NFT actions", tr("Transfer"), tr("Burn"), tr("History"))
	switch a.nft.opTab {
	case 0:
		formCard(c, "Transfer", "Move an NFT to a new owner; the transfer is signed by the current one.", func() {
			field(c, "NFT ID", &a.nft.transferID)
			field(c, "From (base64 public key)", &a.nft.from)
			field(c, "To (base64 public key)", &a.nft.to)
			field(c, "From Private Key", &a.nft.priv)
			a.useCreatorKeyButton(c, &a.nft.priv, a.nft.transferID, a.nft.from)
			a.useSavedKeyButton(c, a.nft.from, &a.nft.priv)
			ui.Row(c).Children(func() {
				if primaryButton(c, "Transfer").Disabled(!allSet(a.nft.transferID, a.nft.from, a.nft.to, a.nft.priv)).Clicked() {
					a.transferNFT()
				}
			})
		})

	case 1:
		formCard(c, "Burn", "Destroy an NFT permanently. This cannot be undone.", func() {
			field(c, "NFT ID", &a.nft.burnID)
			field(c, "Owner (base64 public key)", &a.nft.burnOwner)
			field(c, "Owner Private Key", &a.nft.burnPriv)
			a.useCreatorKeyButton(c, &a.nft.burnPriv, a.nft.burnID, a.nft.burnOwner)
			a.useSavedKeyButton(c, a.nft.burnOwner, &a.nft.burnPriv)
			burnReady := allSet(a.nft.burnID, a.nft.burnOwner, a.nft.burnPriv)
			ui.Row(c).Children(func() {
				// A destructive action carries the danger style, and the
				// confirmation still stands between it and the write.
				burn := dangerButton(c, "Burn NFT…").Disabled(!burnReady).Bind(&a.nft.burnTrigger)
				if burn.Clicked() {
					a.nft.askBurn = true
				}
			})
		})

	case 2:
		formCard(c, "History", "Every mint, transfer and burn recorded for this NFT.", func() {
			field(c, "NFT ID", &a.nft.historyID)
			ui.Row(c).Children(func() {
				if secondaryButton(c, "Show History").Disabled(!allSet(a.nft.historyID)).Clicked() {
					a.readNFTHistory()
				}
			})
			id := strings.TrimSpace(a.nft.historyID)
			matches := id != "" && a.nft.historyLoadedID == id
			if a.nft.historyErr != nil && matches &&
				!loadWarning(c, "Couldn't load NFT history", a.nft.historyErr, len(a.nft.history) > 0) {
				return
			}
			if !matches {
				emptyNote(c, "No history loaded yet.")
				return
			}
			a.nftHistoryTable(c)
		})
	}
}

func (a *App) readNFTHistory() {
	id := strings.TrimSpace(a.nft.historyID)
	if rejectIncomplete(&a.nft.status, "NFT ID is required for this read.", id) {
		return
	}
	a.clearNFTHistoryForAnotherSubject(id)
	if err := a.loadNFTHistoryPage(id, 0); err != nil {
		a.nft.status = errStatus(err)
	} else {
		a.nft.status = statusLine{}
	}
}

// loadNFTDetails reads one asset into the Inspect card. A failure keeps the
// rows only when they were loaded for the same id; the caller invalidates them
// when the subject changes.
func (a *App) loadNFTDetails(id string) error {
	details, err := a.services.GetNFT(id)
	if err != nil {
		a.nft.nftErr = err
		a.nft.nftLoadedID = id
		return err
	}
	a.nft.nft = &details
	a.nft.nftLoadedID = id
	a.nft.nftErr = nil
	if strings.TrimSpace(a.nft.transferID) == id && a.nft.transferOwnerID != id {
		a.applyNFTTransferSubject(details.Owner)
	}
	if strings.TrimSpace(a.nft.burnID) == id && a.nft.burnOwnerID != id {
		a.applyNFTBurnSubject(details.Owner)
	}
	return nil
}

func (a *App) clearNFTDetailsForAnotherSubject(id string) {
	if a.nft.nftLoadedID == id {
		return
	}
	a.nft.nft = nil
	a.nft.nftErr = nil
	a.nft.nftLoadedID = ""
}

// loadNFTHistory reads one asset's operation log. The id is the whole key: a
// failure keeps the rows only when they describe the same asset.
func (a *App) loadNFTHistory(id string) error {
	offset := a.nft.historyOffset
	if a.nft.historyLoadedID != id {
		offset = 0
	}
	return a.loadNFTHistoryPage(id, offset)
}

// loadNFTHistoryPage commits the subject, offset and rows only after a
// successful read. A failed refresh or pager move therefore leaves the visible
// trail and its position on the page they actually describe.
func (a *App) loadNFTHistoryPage(id string, offset int) error {
	if offset < 0 {
		offset = 0
	}
	ops, err := a.services.NFTHistory(id, nftHistoryPageSize+1, offset)
	if err != nil {
		a.nft.historyErr = err
		a.nft.historyLoadedID = id
		return err
	}
	if len(ops) == 0 && offset > 0 {
		return a.loadNFTHistoryPage(id, 0)
	}
	a.nft.historyOffset = offset
	a.nft.historyHasMore = len(ops) > nftHistoryPageSize
	if a.nft.historyHasMore {
		ops = ops[:nftHistoryPageSize]
	}
	a.nft.history = ops
	a.nft.historyLoadedID = id
	a.nft.historyErr = nil
	return nil
}

func (a *App) clearNFTHistoryForAnotherSubject(id string) {
	if a.nft.historyLoadedID == id {
		return
	}
	a.nft.history = nil
	a.nft.historyErr = nil
	a.nft.historyLoadedID = ""
	a.nft.historyOffset = 0
	a.nft.historyHasMore = false
}

// selectNFT re-reads the Inspect card and history for the asset just chosen:
// both would otherwise keep describing the previously selected NFT. The
// readouts are invalidated before the read, so a failure cannot leave the old
// asset's rows under the new id.
func (a *App) selectNFT(id string) {
	if a.nft.nft != nil || a.nft.nftLoadedID != "" || a.nft.nftErr != nil {
		a.clearNFTDetailsForAnotherSubject(id)
		_ = a.loadNFTDetails(id)
	}
	if len(a.nft.history) > 0 || a.nft.historyLoadedID != "" || a.nft.historyErr != nil {
		a.clearNFTHistoryForAnotherSubject(id)
		_ = a.loadNFTHistory(id)
	}
}

// useCreatorKeyButton offers the private key generated by the Mint card to a
// transfer or burn that still signs as the creator. It disappears once the
// asset has moved to another owner or another asset is the subject.
func (a *App) useCreatorKeyButton(c *ui.Context, target *string, nftID, holder string) {
	if a.nft.creatorPriv == "" || a.nft.creatorKeyNFTID == "" ||
		a.nft.creatorKeyNFTID != strings.TrimSpace(nftID) ||
		strings.TrimSpace(holder) != a.nft.creator {
		return
	}
	if quietButton(c, "Use generated creator key").Clicked() {
		*target = a.nft.creatorPriv
	}
}

// transferNFT moves the asset named by the Transfer card.
func (a *App) transferNFT() {
	privateKey := strings.TrimSpace(a.nft.priv)
	id := strings.TrimSpace(a.nft.transferID)
	from, to := strings.TrimSpace(a.nft.from), strings.TrimSpace(a.nft.to)
	if rejectIncomplete(&a.nft.status, "NFT ID, sender, recipient, and private key are required.", id, from, to, privateKey) {
		return
	}
	a.runWrite("Transferring NFT…", func() func() {
		err := a.services.TransferNFT(id, from, to, privateKey)
		return func() {
			a.nft.status = wrapErr(err)
			if err == nil {
				a.rememberSuccessfulKey(from, privateKey)
				// The recipient is the asset's holder now. Move both holder-shaped
				// forms only when they target this asset; Transfer and Burn have
				// independent ids, so a write to one must not retarget the other.
				a.applyNFTTransferSubject(to)
				if strings.TrimSpace(a.nft.burnID) == id {
					a.applyNFTBurnSubject(to)
				}
				a.refreshNFT(id)
			}
		}
	})
}

// refreshNFTPage re-reads the collection and the Inspect/history cards that are
// already showing something, for the Refresh action. A write targets the id it
// changed and goes through refreshNFT.
func (a *App) refreshNFTPage() {
	a.loadNFT()
	if a.nft.nft != nil || a.nft.nftLoadedID != "" || a.nft.nftErr != nil {
		id := strings.TrimSpace(a.nft.id)
		a.clearNFTDetailsForAnotherSubject(id)
		_ = a.loadNFTDetails(id)
	}
	if len(a.nft.history) > 0 || a.nft.historyLoadedID != "" || a.nft.historyErr != nil {
		id := strings.TrimSpace(a.nft.historyID)
		a.clearNFTHistoryForAnotherSubject(id)
		_ = a.loadNFTHistory(id)
	}
}

// refreshNFT re-reads what a write just changed: the collection, plus the
// Inspect readout and history when they are already showing id. A successful
// transfer that left the old owner in the collection read as a failed write.
func (a *App) refreshNFT(id string) {
	a.loadNFT()
	if id == "" {
		return
	}
	if (a.nft.nft != nil || a.nft.nftLoadedID != "" || a.nft.nftErr != nil) && a.nft.nftLoadedID == id {
		_ = a.loadNFTDetails(id)
	}
	if (len(a.nft.history) > 0 || a.nft.historyLoadedID != "" ||
		a.nft.historyErr != nil) && a.nft.historyLoadedID == id {
		_ = a.loadNFTHistory(id)
	}
}

func (a *App) nftHistoryTable(c *ui.Context) {
	if len(a.nft.history) == 0 {
		emptyNote(c, "No operations recorded for this NFT.")
		return
	}
	if previous, next := listPager(c, "NFT operation history", a.nft.historyOffset, len(a.nft.history), a.nft.historyHasMore); previous || next {
		target := a.nft.historyOffset
		if previous {
			target = max(0, target-nftHistoryPageSize)
		} else {
			target += nftHistoryPageSize
		}
		_ = a.loadNFTHistoryPage(a.nft.historyLoadedID, target)
		return
	}
	ops := a.nft.history
	if stackedRecords(c) {
		nftHistoryRecords(c, ops)
	} else {
		namedTable(c, "NFT operation history", &a.nft.historyTable, []ui.TableColumn{
			{Title: tr("Type"), Width: 100},
			{Title: tr("From"), Width: 160},
			{Title: tr("To"), Width: 160},
			{Title: tr("Block"), MinWidth: tableColumnWidth(c, 140), Align: ui.End},
		}, len(ops), func(row, col int) {
			op := ops[row]
			switch col {
			case 0:
				tableText(c, tr(op.Type))
			case 1:
				tableText(c, op.From)
			case 2:
				tableText(c, op.To)
			case 3:
				tableText(c, strconv.FormatInt(op.BlockHeight, 10))
			}
		})
	}
}

// nftHistoryRecords keeps the operation, exact block and both account keys
// together when the four-column trail no longer fits enlarged text.
func nftHistoryRecords(c *ui.Context, operations []NFTOpRow) {
	ui.Column(c).FillWidth().Gap(10).Children(func() {
		for _, operation := range operations {
			operation := operation
			recordPanel(c, func() {
				ui.Row(c).FillWidth().Wrap().Gap(18).AlignItems(ui.Center).Children(func() {
					ui.Text(c, tr(operation.Type)).FontSize(textSize(c, 13)).Bold().
						TextColor(c.Theme().Text)
					recordMetric(c, "Block", strconv.FormatInt(operation.BlockHeight, 10), c.Theme().Text)
				})
				recordField(c, "From", valueOr(operation.From))
				recordField(c, "To", valueOr(operation.To))
			})
		}
	})
}

func (a *App) renderNFTBurnDialog(c *ui.Context) {
	if !a.nft.askBurn {
		return
	}
	// Say which asset is about to be destroyed. A name is friendlier than a
	// UUID, but only when the Inspect card loaded that same asset.
	detail := tr("The asset is destroyed and cannot be recovered.")
	if id := strings.TrimSpace(a.nft.burnID); id != "" {
		target := shortID(id)
		if a.nft.nft != nil && a.nft.nft.ID == id && a.nft.nft.Name != "" {
			target = conciseText(a.nft.nft.Name, 32) + " (" + shortID(id) + ")"
		}
		detail = fmt.Sprintf(tr("Burn %s? The asset is destroyed and cannot be recovered."), target)
	}
	switch destructiveConfirm(c, &a.nft.askBurn, tr("Burn this NFT?"), detail, tr("Burn"),
		a.nft.burnTrigger, a.nft.burnTrigger) {
	case destructiveConfirmed:
		id := strings.TrimSpace(a.nft.burnID)
		privateKey := strings.TrimSpace(a.nft.burnPriv)
		owner := strings.TrimSpace(a.nft.burnOwner)
		if !allSet(id, owner, privateKey) {
			a.nft.status = errorStatus("NFT ID, owner, and private key are required.")
			return
		}
		a.runWrite("Burning NFT…", func() func() {
			err := a.services.BurnNFT(id, owner, privateKey)
			return func() {
				a.nft.status = wrapErr(err)
				if err == nil {
					a.rememberSuccessfulKey(owner, privateKey)
					a.nft.burnPriv = ""
					// The asset is gone, so reading it again is not a failure to
					// report: clear the Inspect card directly and re-read the history,
					// which now ends with the burn.
					a.loadNFT()
					if a.nft.nftLoadedID == id || (a.nft.nft != nil && a.nft.nft.ID == id) {
						a.nft.nft = nil
						a.nft.nftErr = nil
						a.nft.nftLoadedID = ""
					}
					if a.nft.historyLoadedID == id {
						_ = a.loadNFTHistory(id)
					}
				}
			}
		})
	}
}
